const int tid = (int)thread_position_in_threadgroup.x;
const uint lane = thread_index_in_simdgroup;
const uint sg = simdgroup_index_in_threadgroup;
const int K = act_shape[1];
const int n = dq_shape[0];
const int r = (int)threadgroup_position_in_grid.y;
const int j0 = (int)threadgroup_position_in_grid.x * BN;
const int KP = K / 8;
const int KG = K / 64;
auto a_row = act + (size_t)r * (size_t)K;
float acc[BN];
int offq[BN];
int offs[BN];
for (int i = 0; i < BN; i++) {
  acc[i] = 0.0f;
  int jj = min(j0 + i, n - 1);
  offq[i] = jj * KP;
  offs[i] = jj * KG;
}
for (int c = tid; c < KP; c += TG) {
  uint w[BN];
  float sc[BN];
  float bi[BN];
  int g = c >> 3;
  for (int i = 0; i < BN; i++) {
    w[i] = dq[offq[i] + c];
    sc[i] = float(ds[offs[i] + g]);
    bi[i] = float(db[offs[i] + g]);
  }
  auto ap = a_row + c * 8;
  float a0 = float(ap[0]);
  float a1 = float(ap[1]);
  float a2 = float(ap[2]);
  float a3 = float(ap[3]);
  float a4 = float(ap[4]);
  float a5 = float(ap[5]);
  float a6 = float(ap[6]);
  float a7 = float(ap[7]);
  float asum = ((a0 + a1) + (a2 + a3)) + ((a4 + a5) + (a6 + a7));
  float b1 = a1 * 0.0625f;
  float b2 = a2 * 0.00390625f;
  float b3 = a3 * 0.000244140625f;
  float b5 = a5 * 0.0625f;
  float b6 = a6 * 0.00390625f;
  float b7 = a7 * 0.000244140625f;
  for (int i = 0; i < BN; i++) {
    uint lo = w[i] & 0xffffu;
    uint hi = w[i] >> 16;
    float d = a0 * float(lo & 0xfu);
    d = fma(b1, float(lo & 0xf0u), d);
    d = fma(b2, float(lo & 0xf00u), d);
    d = fma(b3, float(lo & 0xf000u), d);
    d = fma(a4, float(hi & 0xfu), d);
    d = fma(b5, float(hi & 0xf0u), d);
    d = fma(b6, float(hi & 0xf00u), d);
    d = fma(b7, float(hi & 0xf000u), d);
    acc[i] = fma(sc[i], d, fma(bi[i], asum, acc[i]));
  }
}
threadgroup float red[(TG / 32) * BN];
for (int i = 0; i < BN; i++) {
  float v = simd_sum(acc[i]);
  if (lane == 0) red[sg * BN + i] = v;
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tid < BN) {
  int j = j0 + tid;
  if (j < n) {
    float s = 0.0f;
    for (int q = 0; q < TG / 32; q++) s += red[q * BN + tid];
    size_t o = (size_t)r * (size_t)n + (size_t)j;
    out[o] = T(float(x[o]) + float(res[o]) + s);
  }
}
